param([Parameter(Mandatory=$true)][string]$InstallerUrl,[string]$OutFile="$env:RUNNER_TEMP\asc-ui-tree-probe.json")
$ErrorActionPreference='Stop';Add-Type -AssemblyName UIAutomationClient;Add-Type -AssemblyName UIAutomationTypes
$tmp=Join-Path $env:RUNNER_TEMP 'asc-ui-probe';New-Item -ItemType Directory -Force $tmp|Out-Null;$installer=Join-Path $tmp 'asc.exe';Invoke-WebRequest -UseBasicParsing $InstallerUrl -OutFile $installer
$seven=Get-Command 7z.exe -ErrorAction Stop;$extract=Join-Path $tmp 'extract';New-Item -ItemType Directory -Force $extract|Out-Null;& $seven.Source x '-y' "-o$extract" $installer *> (Join-Path $tmp '7z.log')
$roz=Get-ChildItem $extract -Recurse -File -Filter roz.exe|Select-Object -First 1;if(-not $roz){throw 'ASC_ROZ_EXE_NOT_FOUND'}
$p=Start-Process -FilePath $roz.FullName -PassThru;try{$desktop=[System.Windows.Automation.AutomationElement]::RootElement;$pidCond=New-Object System.Windows.Automation.PropertyCondition([System.Windows.Automation.AutomationElement]::ProcessIdProperty,$p.Id);$deadline=(Get-Date).AddSeconds(25);$roots=$null;do{Start-Sleep -Milliseconds 500;$roots=$desktop.FindAll([System.Windows.Automation.TreeScope]::Children,$pidCond)}while($roots.Count-lt 1-and(Get-Date)-lt$deadline);if($roots.Count-lt 1){throw 'ASC_UI_PROCESS_ROOT_NOT_FOUND'};$root=$roots.Item(0)
 $all=$root.FindAll([System.Windows.Automation.TreeScope]::Descendants,[System.Windows.Automation.Condition]::TrueCondition);$nodes=@();for($i=0;$i-lt[Math]::Min($all.Count,1500);$i++){$e=$all.Item($i);try{$c=$e.Current;$nodes+=@{name=$c.Name;automation_id=$c.AutomationId;class_name=$c.ClassName;control_type=$c.ControlType.ProgrammaticName;enabled=$c.IsEnabled;offscreen=$c.IsOffscreen}}catch{}}
 $names=$nodes|Where-Object{$_.name}|Select-Object -ExpandProperty name -Unique;$r=[ordered]@{schema='OKULOS_ASC_UI_AUTOMATION_PROBE_V1';status='UI_PROBED_NOT_GENERATED';generation_status='NOT_RUN';process_id=$p.Id;root_count=$roots.Count;window_title=$root.Current.Name;window_class=$root.Current.ClassName;node_count=$nodes.Count;actionable_names=@($names|Where-Object{$_-match'Create|New|Import|Export|TimeTable|Generate|Start|File|Test|Verification|Close|Cancel|OK'});nodes=$nodes;claim='UI Automation surface probe only; no timetable generation or benchmark claim.'};$r|ConvertTo-Json -Depth 8|Set-Content -Encoding utf8 $OutFile;Get-Content $OutFile
}finally{if(-not$p.HasExited){Stop-Process -Id $p.Id -Force -ErrorAction SilentlyContinue}}
